// ***************
// Filename: baud_nco_top.sv
// Author: FPGA Cores 4 U
// Description: baud_nco with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map baud_nco_regs
//   (u_regs, src/include/baud_nco_regs.sv, ID "BNCO", VERSION and DATE at
//   0x00-0x08, the registers from 0x10) and the logic baud_nco (u_core,
//   src/baud_nco.sv), joined by their register ports (cfg_* to the logic,
//   sts_* back). Generated by ip/scripts/regmap_gen.py from
//   baud_nco_regs.json and the ports of baud_nco: regenerate after changing
//   either. Clock - aclk. Reset - synchronous active low aresetn.
// Date: 2026-10-12
module baud_nco_top #(
  parameter int PHASE_W = 32,
  parameter int CLK_HZ = 100_000_000,
  parameter int BAUD = 115_200,
  parameter int OSR = 16
) (
  input  logic        aclk,
  input  logic        aresetn,
  input  logic [7:0]  s_axil_awaddr,
  input  logic        s_axil_awvalid,
  output logic        s_axil_awready,
  input  logic [31:0] s_axil_wdata,
  input  logic [3:0]  s_axil_wstrb,
  input  logic        s_axil_wvalid,
  output logic        s_axil_wready,
  output logic [1:0]  s_axil_bresp,
  output logic        s_axil_bvalid,
  input  logic        s_axil_bready,
  input  logic [7:0]  s_axil_araddr,
  input  logic        s_axil_arvalid,
  output logic        s_axil_arready,
  output logic [31:0] s_axil_rdata,
  output logic [1:0]  s_axil_rresp,
  output logic        s_axil_rvalid,
  input  logic        s_axil_rready,
  output logic [31:0] m_axis_tdata,
  output logic        m_axis_tvalid,
  input  logic        m_axis_tready,
  output logic        m_axis_tlast,
  output logic        baud_tick_o,
  output logic        sq_o
);
  // Default FCW = round(BAUD * OSR * 2^PHASE_W / CLK_HZ), 64 bit math
  localparam logic [63:0] FCW64 = ((64'(BAUD) * 64'(OSR) << PHASE_W) + (64'(CLK_HZ) >> 1)) / 64'(CLK_HZ);
  localparam logic [31:0] FCW_DEF = FCW64[31:0];
  // register ports between the register map and the logic
  logic [2:0] cfg_ctrl;
  logic cfg_ctrl_wr;
  logic [2:0] sts_ctrl;
  logic [31:0] cfg_fcw;
  logic [15:0] cfg_phase_off;
  logic [14:0] cfg_gain;
  logic [1:0] sts_status;
  logic cfg_tick_count_wr;
  logic [31:0] sts_tick_count;

  baud_nco_regs #(
    .FCW_RST(FCW_DEF)
  ) u_regs (
    .aclk,
    .aresetn,
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .ctrl_o(cfg_ctrl),
    .ctrl_wr_o(cfg_ctrl_wr),
    .ctrl_i(sts_ctrl),
    .fcw_o(cfg_fcw),
    .fcw_wr_o(),
    .phase_off_o(cfg_phase_off),
    .phase_off_wr_o(),
    .gain_o(cfg_gain),
    .gain_wr_o(),
    .status_i(sts_status),
    .tick_count_o(),
    .tick_count_wr_o(cfg_tick_count_wr),
    .tick_count_i(sts_tick_count)
  );
  baud_nco #(
    .PHASE_W(PHASE_W),
    .CLK_HZ(CLK_HZ),
    .BAUD(BAUD),
    .OSR(OSR)
  ) u_core (
    .aclk,
    .aresetn,
    .m_axis_tdata,
    .m_axis_tvalid,
    .m_axis_tready,
    .m_axis_tlast,
    .baud_tick_o,
    .sq_o,
    .cfg_ctrl,
    .cfg_ctrl_wr,
    .sts_ctrl,
    .cfg_fcw,
    .cfg_phase_off,
    .cfg_gain,
    .sts_status,
    .cfg_tick_count_wr,
    .sts_tick_count
  );
endmodule
